for x in r:lines.append('|'+x['m']+'|'+x['mode']+'|'+x['q']+'|'+'|'.join(f(x[k]) for k in ['T','source_Rayleigh','line_below_T','quartet_below_T','Weil_below_T','Weil_T_to_310','unpaid_source_minus_prefix'])+'|')
